// Факт 21.10: новый аккаунт «QA reg 2110» — текст дословно как Figma, по центру, счётчики 0/0/0 (2110-be1e2077-card.png).
// Нужен аккаунт БЕЗ молитв (APP_ACCOUNT с пустой историей). На аккаунте с молитвами карточки нет — тест пропускается (не провал).
// Новый аккаунт автотест не создаёт. Кейс: .qa/tests/home/HM-08-empty-card-text.md.
import { expect } from '@wdio/globals';
import { byTextContains, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { goHome, counter, nodes } from '../_lib/readiness-1910.ts';
import { box, centerX, screenCenterX } from '../_lib/app-2110.ts';

const NEW_TEXT = 'לחץ על "התחל תפילה" כדי להתחיל את התפילה הראשונה שלך';
const OLD_TEXT = 'עדיין לא השלמת אף תפילה';

describe('21.10 — пустая карточка главной (#c75c08)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('HM-08 Аккаунт без молитв: счётчики 0/0/0, карточка «התחל את המסע שלך» с текстом «לחץ על "התחל תפילה"…הראשונה שלך» по центру, старого текста нет, блока «תפילות אחרונות» нет #c75c08 #be1e2077 S-01 AC4 @prod-safe', async function () {
    await goHome();
    const total = await counter('סה״כ תפילות');
    if (total > 0) skipWith(this, `у аккаунта ${total} молитв — нужна учётка без молитв (новая регистрация, вручную)`);
    expect(await counter('תפילות היום')).toBe(0);
    expect(await counter('ימים רצופים')).toBe(0);
    await scrollToText('התחל את המסע שלך');
    // Текст может быть с типографскими кавычками — сверяем по частям без кавычек.
    const labels = (await nodes()).map((n) => n.label).join('\n');
    expect(labels).toContain('התחל תפילה');
    expect(labels).toContain('כדי להתחיל את התפילה הראשונה שלך');
    expect(labels).not.toContain(OLD_TEXT);
    expect(await shown(byTextContains('תפילות אחרונות'))).toBe(false);
    const el = (await byTextContains('כדי להתחיל את התפילה הראשונה שלך')) as unknown as WebdriverIO.Element;
    const d = Math.abs(centerX(await box(el)) - (await screenCenterX()));
    console.log(`[HM-08] эталон «${NEW_TEXT}»; Δ центра текста ${d.toFixed(1)} pt`);
    expect(d).toBeLessThanOrEqual(8);
  });
});
